def intro(kicker,title,desc):
    return f'<section class="wrap inner-hero"><a class="breadcrumb" href="/">← Back to the field guide</a><p class="eyebrow lime">{kicker}</p><h1>{title}</h1><p class="inner-description">{desc}</p></section>'

controls = intro('THE ESSENTIALS / CONTROLS','Brisbane Streets<br><span>controls.</span>','A quick-reference guide for your next session.') + '''<section class="wrap controls-section"><div class="tablist" hidden role="tablist" aria-label="Choose device"><button id="desktop-tab" role="tab" aria-selected="true" aria-controls="desktop">Desktop</button><button id="mobile-tab" role="tab" aria-selected="false" aria-controls="mobile" tabindex="-1">Mobile / touch</button></div><div id="desktop" role="tabpanel" aria-labelledby="desktop-tab"><h2>Start here.</h2><div class="control-grid"><article class="control-card"><kbd>W A S D</kbd><h3>Move</h3></article><article class="control-card"><kbd>Mouse</kbd><h3>Look around</h3></article><article class="control-card"><kbd>Shift</kbd><h3>Sprint</h3></article><article class="control-card"><kbd>Space</kbd><h3>Jump</h3></article><article class="control-card"><kbd>E</kbd><h3>Interact</h3></article><article class="control-card"><kbd>M</kbd><h3>Open map</h3></article><article class="control-card"><kbd>J</kbd><h3>Missions</h3></article><article class="control-card"><kbd>Esc</kbd><h3>Pause &amp; settings</h3></article></div><div class="note-box"><span class="lime">↳</span><div><h3>Behind the wheel?</h3><p>WASD steers and drives. Shift or Space acts as a handbrake. E gets you in or out.</p></div></div></div><div id="mobile" role="tabpanel" aria-labelledby="mobile-tab"><h2>Two thumbs. A whole city.</h2><div class="touch-grid"><article class="touch-card"><div class="thumb-disc" aria-hidden="true">↔</div><h3>Left thumb</h3><p>Move, drive or ride. Push to the edge to sprint.</p></article><article class="touch-card"><div class="thumb-disc" aria-hidden="true">◎</div><h3>Right thumb</h3><p>Look around. Use two fingers to adjust the camera.</p></article><article class="touch-card"><div class="thumb-disc" aria-hidden="true">E</div><h3>On-screen buttons</h3><p>Tap the labelled controls to interact, jump and open the map.</p></article></div></div><p class="source-note">Reference: <a href="https://brisbane-streets.pages.dev/" target="_blank" rel="noopener">official in-game controls ↗</a> · Checked 5 November 2026. Controls may change with updates.</p></section>'''

unblocked = intro('PLAY & TROUBLESHOOT','Brisbane Streets<br><span>unblocked?</span>','Looking for Brisbane Streets unblocked? Start with the official destination.') + '''<section class="wrap section compact"><div class="destination"><div class="destination-icon" aria-hidden="true">↗</div><div><p class="eyebrow lime">DEVELOPER’S WEBSITE</p><h2>Brisbane Streets</h2><p class="url">brisbane-streets.pages.dev</p></div><a class="button" href="https://brisbane-streets.pages.dev/" target="_blank" rel="noopener">Open official game ↗</a></div><div class="section-heading"><div><p class="eyebrow muted">A QUICK CHECKLIST</p><h2>Not loading? Start here.</h2></div></div><div class="help-grid"><article><span class="step-number">01</span><h3>Check the address</h3><p>Open the official link above directly. Avoid downloads claiming to unlock the game.</p></article><article><span class="step-number">02</span><h3>Update your browser</h3><p>Try a current browser, reload once, and close other demanding tabs.</p></article><article><span class="step-number">03</span><h3>Check your network</h3><p>A managed school or work network may block games. Ask the administrator about permitted access.</p></article><article><span class="step-number">04</span><h3>Check with the developer</h3><p>If the official site is unavailable, use the support links there when it returns.</p></article></div><div class="note-box"><span class="lime">↳</span><div><h3>“Unblocked” isn’t a guarantee.</h3><p>This guide cannot remove network restrictions. We do not provide mirrors or modified game files.</p></div></div></section>'''

