game_intro = '''<section class="wrap game-overview" aria-labelledby="game-overview-title"><div class="section-heading"><div><p class="eyebrow muted">THE GAME / AT A GLANCE</p><h2 id="game-overview-title">What is Brisbane Streets?</h2></div><a class="text-link" href="/about/">Sources &amp; independence ↗</a></div><div class="overview-grid"><article><span class="overview-symbol" aria-hidden="true">↗</span><h3>A city to explore</h3><p>A browser-based city game with walking, driving and missions. Start playing on the developer’s website.</p></article><article><span class="overview-symbol" aria-hidden="true">⌘</span><h3>Choose your controls</h3><p>Use keyboard and mouse, or touch controls. This guide covers the basics and useful shortcuts.</p><a class="text-link" href="/controls/">Pick your device →</a></article><article><span class="overview-symbol" aria-hidden="true">◎</span><h3>Know before you join</h3><p>The developer lists online play for ages 13+. The game contains violence and strong language.</p><a class="text-link" href="https://brisbane-streets.pages.dev/safety.html" target="_blank" rel="noopener">Official safety information ↗</a></article></div><p class="source-note">Based on the <a href="https://brisbane-streets.pages.dev/" target="_blank" rel="noopener">official game interface ↗</a> · Reviewed 5 November 2026. City photography is not game footage.</p></section>'''
