controls = controls.replace('<div class="note-box"><span class="lime">↳</span><div><h3>Behind the wheel?</h3>', advanced_controls + '<div class="note-box"><span class="lime">↳</span><div><h3>Behind the wheel?</h3>')

save_help = '''<div class="note-box"><span class="lime">↳</span><div><h3>Protect your save before troubleshooting.</h3><p>The game saves in your browser. Export a copy from its settings before clearing site data or changing devices.</p></div></div>'''
unblocked = unblocked.replace('<div class="note-box"><span class="lime">↳</span><div><h3>“Unblocked”', save_help + '<div class="note-box"><span class="lime">↳</span><div><h3>“Unblocked”')

pages = {'':('Brisbane Streets Game — Unofficial Player Guide','Find the official Brisbane Streets game, desktop and mobile controls, and quick loading help in an independent fan guide.',home),'controls/':('Brisbane Streets Controls — Desktop & Mobile Guide','Find Brisbane Streets desktop keys and touch controls in a clear, quick-reference guide.',controls),'unblocked/':('Brisbane Streets Unblocked — Official Link & Loading Help','Find the official Brisbane Streets game website and a practical checklist for browser or loading problems.',unblocked),'about/':('About & Sources — Brisbane Streets Field Guide','About this independent Brisbane Streets fan guide, its sources and photography credits.',about),'privacy/':('Privacy — Brisbane Streets Field Guide','Privacy information for the independent Brisbane Streets fan guide.',privacy)}
for route,(title,desc,content) in pages.items():
    folder=P/route;folder.mkdir(parents=True,exist_ok=True)
    (folder/'index.html').write_text(page(title,desc,content,route),encoding='utf-8')
(P/'404.html').write_text(page('Page Not Found — Brisbane Streets Guide','Find your way back to the Brisbane Streets field guide.',intro('404 / WRONG TURN','A little off course.','This page isn’t here. Your next adventure still is.')+'<div class="wrap section compact"><a class="button" href="/">Back to the guide →</a></div>','404.html'),encoding='utf-8')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /designs/\nSitemap: '+DOMAIN+'/sitemap.xml\n',encoding='utf-8')
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{DOMAIN}/{route}</loc><lastmod>2026-11-05</lastmod></url>\n' for route in pages)+'</urlset>\n',encoding='utf-8')
(P/'_redirects').write_text('/characters / 301\n/characters/ / 301\n/how-to-play /controls/ 301\n/how-to-play/ /controls/ 301\n/where-to-play /unblocked/ 301\n/where-to-play/ /unblocked/ 301\n',encoding='utf-8')
(P/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#d7f956"/><text x="16" y="47" font-family="Arial" font-size="43" font-weight="900" fill="#141713">B</text></svg>',encoding='utf-8')

if __name__=='__main__':
    files = ['index.html','style.css','site.js','404.html','robots.txt','sitemap.xml','_redirects','favicon.svg','favicon.ico','apple-touch-icon.png','og.png','og.svg']
    for name in files:
        if (P/name).exists(): shutil.copy2(P/name,ROOT/name)
    for route in ['controls','unblocked','about','privacy','assets']:
        shutil.copytree(P/route,ROOT/route,dirs_exist_ok=True)
    # Keep legacy files as functional fallbacks on hosts without redirect support.
    for old,new in [('characters','/'),('how-to-play','/controls/'),('where-to-play','/unblocked/')]:
        (ROOT/old/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url={new}"><link rel="canonical" href="{DOMAIN}{new}"><title>Guide moved</title></head><body style="font:18px/1.6 system-ui"><a href="{new}">Continue to the Brisbane Streets guide</a></body></html>',encoding='utf-8')
    parser = argparse.ArgumentParser(description='Build the static site and optionally export a clean deployment folder.')
    parser.add_argument('--output', help='Output directory, relative to repository root or absolute; no files are deleted.')
    args = parser.parse_args()
    if args.output:
        output = (ROOT / args.output).resolve()
        if output == ROOT or output == P or output in P.parents:
            parser.error('Choose a separate deployment directory, for example dist.')
        output.mkdir(parents=True, exist_ok=True)
        for name in files:
            if (P/name).exists(): shutil.copy2(P/name,output/name)
        for route in ['controls','unblocked','about','privacy','assets']:
            shutil.copytree(P/route,output/route,dirs_exist_ok=True)
        print(f'Clean site exported to {output}. Choose a new or empty folder to avoid stale unrelated files.')
    print('Built and synced 5 pages, 404, redirects and static assets.')
